import Navbar from "./components/navbar.jsx";
import Footer from "./components/footer.jsx";
import Hero from "./sections/Hero.jsx";
import About from "./sections/About.jsx";
import Experience from "./sections/Experience.jsx";
import Projects from "./sections/Projects.jsx";
import Achievements from "./sections/Achievements.jsx";
import Contact from "./sections/Contact.jsx";

const BRAND = "nauffalrn";

// The whole public page. Rendered to static HTML at build time
// (src/entry-server.jsx) and hydrated in the browser (src/entry-client.jsx),
// both from the same `content` generated by scripts/build-content.mjs.
const PublicSite = ({ content }) => {
  const { profile, experiences, projects, certificates } = content;

  return (
    <>
      <a
        href="#main"
        className="sr-only focus:not-sr-only focus:fixed focus:top-3 focus:left-3 focus:z-50 focus:rounded-md focus:bg-accent-strong focus:px-4 focus:py-2 focus:font-semibold focus:text-accent-ink"
      >
        Skip to content
      </a>
      <div className="site-bg" aria-hidden="true" />
      <Navbar brand={BRAND} />
      <main id="main" tabIndex={-1} className="pt-24 focus:outline-none">
        <Hero profile={profile} experiences={experiences} />
        <About profile={profile} />
        <Experience experiences={experiences} />
        <Projects projects={projects} />
        <Achievements certificates={certificates} />
        <Contact profile={profile} />
      </main>
      <Footer profile={profile} brand={BRAND} />
    </>
  );
};

export default PublicSite;
